#include <stdbool.h>
#include <stddef.h>

/*
 * A chart item identifies one Earley state.  position is the chart set in
 * which the item is stored; origin is the position at which its production
 * began.  All fields participate in item identity, including position.
 */
typedef struct {
    size_t production;
    size_t alternative;
    size_t dot;
    size_t origin;
    size_t position;
} PbnfcChartItem;

typedef struct {
    PbnfcChartItem *items;
    size_t count;
    size_t capacity;
} PbnfcChartSet;

typedef struct {
    PbnfcChartSet *sets;
    size_t set_count;
} PbnfcChart;

typedef enum {
    PBNFC_CHART_INSERT_ERROR = -1,
    PBNFC_CHART_INSERT_DUPLICATE = 0,
    PBNFC_CHART_INSERTED = 1
} PbnfcChartInsertResult;

/* Initialize an item value without allocating ownership. */
PbnfcChartItem pbnfc_chart_item_make(size_t production,
                                     size_t alternative,
                                     size_t dot,
                                     size_t origin,
                                     size_t position);

bool pbnfc_chart_item_equal(const PbnfcChartItem *left,
                            const PbnfcChartItem *right);

/* Allocate position_count ordered sets. A zero-position chart is valid. */
bool pbnfc_chart_init(PbnfcChart *chart, size_t position_count);
void pbnfc_chart_free(PbnfcChart *chart);

size_t pbnfc_chart_set_count(const PbnfcChart *chart);
PbnfcChartSet *pbnfc_chart_set(PbnfcChart *chart, size_t position);
const PbnfcChartSet *pbnfc_chart_set_const(const PbnfcChart *chart,
                                            size_t position);

/*
 * Insert into the set selected by item->position. Items are retained in
 * insertion order and equal items are not appended a second time.
 */
PbnfcChartInsertResult pbnfc_chart_insert(PbnfcChart *chart,
                                          const PbnfcChartItem *item);

size_t pbnfc_chart_set_size(const PbnfcChartSet *set);
const PbnfcChartItem *pbnfc_chart_set_at(const PbnfcChartSet *set,
                                         size_t index);

#endif

#include "grammar_ast.h"
#include "markup_lexer.h"
#include "recognizer.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int fail(const char *detail)
{
    (void)fprintf(stderr, "parallel closure smoke: %s\n", detail);
    return 1;
}

static PbnfcGrammar *parse_grammar(const char *source)
{
    PbnfcGrammar *grammar = NULL;

    if (!pbnfc_grammar_parse(source, strlen(source), NULL, &grammar) ||
        !pbnfc_grammar_validate(grammar, NULL)) {
        pbnfc_grammar_free(grammar);
        return NULL;
    }
    return grammar;
}

static bool lex_input(const char *source,
                      PbnfcMarkupToken **tokens_out,
                      size_t *count_out)
{
    PbnfcMarkupLexer lexer;
    PbnfcMarkupToken token;
    PbnfcMarkupToken *tokens = NULL;
    size_t count = 0U;
    size_t capacity = 0U;

    pbnfc_markup_lexer_init(&lexer, source, strlen(source), NULL);
    for (;;) {
        if (!pbnfc_markup_lexer_next(&lexer, &token)) {
            free(tokens);
            return false;
        }
        if (token.kind == PBNFC_MARKUP_TOKEN_EOF) {
            break;
        }
        if (count == capacity) {
            size_t next_capacity = capacity == 0U ? 16U : capacity * 2U;
            PbnfcMarkupToken *next_tokens =
                (PbnfcMarkupToken *)realloc(tokens,
                                             next_capacity * sizeof(*tokens));
            if (next_tokens == NULL) {
                free(tokens);
                return false;
            }
            tokens = next_tokens;
            capacity = next_capacity;
        }
        tokens[count] = token;
        ++count;
    }
    *tokens_out = tokens;
    *count_out = count;
    return true;
}

int main(void)
{
    static const char grammar_source[] =
        "%start Document\n"
        "%token TEXT\n"
        "Document ::= Nodes ;\n"
        "Nodes ::= Node Nodes | ;\n"
        "Node ::= Text | Group ;\n"
        "Text ::= $TEXT ;\n"
        "Group ::= '<' 'a' '>' Nodes '<' '/' 'a' '>' ;\n";
    static const char input_source[] =
        "<a>one<a>two</a>three<a>four<a>five</a></a></a>"
        "<a>six</a>seven<a>eight</a>";
    PbnfcGrammar *grammar = parse_grammar(grammar_source);
    PbnfcMarkupToken *tokens = NULL;
    size_t token_count = 0U;
    PbnfcRecognitionStats stats;
    PbnfcRecognitionResult result;
    size_t worker_index;

    if (grammar == NULL || !lex_input(input_source, &tokens, &token_count)) {
        pbnfc_grammar_free(grammar);
        free(tokens);
        return fail("parallel smoke input did not prepare");
    }
    result = pbnfc_recognize_parallel(grammar,
                                      tokens,
                                      token_count,
                                      NULL,
                                      &stats);
    if (result != PBNFC_RECOGNITION_ACCEPTED) {
        free(tokens);
        pbnfc_grammar_free(grammar);
        return fail("parallel chart did not accept nested input");
    }
    if (stats.workers != PBNFC_WORKER_POOL_SIZE ||
        stats.active_workers != PBNFC_WORKER_POOL_SIZE || stats.rounds == 0U) {
        free(tokens);
        pbnfc_grammar_free(grammar);
        return fail("parallel run did not report eight active workers");
    }
    for (worker_index = 0U;
         worker_index < PBNFC_WORKER_POOL_SIZE;
         ++worker_index) {
        if (stats.tasks[worker_index] == 0U) {
            free(tokens);
            pbnfc_grammar_free(grammar);
            return fail("a worker did not receive chart work");
        }
    }
    result = pbnfc_recognize_parallel(grammar,
                                      tokens,
                                      token_count,
                                      NULL,
                                      &stats);
    free(tokens);
    pbnfc_grammar_free(grammar);
    if (result != PBNFC_RECOGNITION_ACCEPTED || stats.rounds == 0U) {
        return fail("parallel result was not repeatable");
    }
    return 0;
}
}

PbnfcRecognitionResult pbnfc_recognize_parallel(
    const PbnfcGrammar *grammar,
    const PbnfcMarkupToken *tokens,
    size_t token_count,
    const char *start_name,
    PbnfcRecognitionStats *stats)
{
    return pbnfc_recognize_parallel_with_diagnostics(grammar,
                                                     tokens,
                                                     token_count,
                                                     start_name,
                                                     NULL,
                                                     stats);
}

PbnfcRecognitionResult pbnfc_recognize_parallel_with_diagnostics(
    const PbnfcGrammar *grammar,
    const PbnfcMarkupToken *tokens,
    size_t token_count,
    const char *start_name,
    const PbnfcDiagnosticContext *diagnostics,
    PbnfcRecognitionStats *stats)
{
    PbnfcChart chart;
    PbnfcWorkerPool pool = {0};
    PbnfcParallelGeneration generation = {0};
    size_t start_production;
    size_t alternative;
    size_t position;
    size_t rejection_position = 0U;
    const PbnfcChartSet *rejection_set = NULL;
    const char *effective_start;
    char *expected = NULL;
    PbnfcLocation rejection_location;
    PbnfcRecognitionResult result = PBNFC_RECOGNITION_ERROR;

    if (stats != NULL) {
        (void)memset(stats, 0, sizeof(*stats));
    }
    if (grammar == NULL || (tokens == NULL && token_count != 0U) ||
        grammar->start_count == 0U) {
        return PBNFC_RECOGNITION_ERROR;
    }
    effective_start = start_name == NULL ? grammar->start_name : start_name;
    if (effective_start == NULL ||
        !production_index(grammar, effective_start, &start_production) ||
        token_count == SIZE_MAX || !pbnfc_chart_init(&chart, token_count + 1U)) {
        return PBNFC_RECOGNITION_ERROR;
    }
    if (!pbnfc_worker_pool_init(&pool)) {
        pbnfc_chart_free(&chart);
        return PBNFC_RECOGNITION_ERROR;
    }
    if (stats != NULL) {
        stats->workers = pbnfc_worker_pool_worker_count(&pool);
        stats->active_workers = stats->workers;
    }
    generation.chart = &chart;
    generation.grammar = grammar;
    generation.tokens = tokens;
    generation.token_count = token_count;
    for (alternative = 0U;
         alternative < grammar->productions[start_production].alternative_count;
         ++alternative) {
        if (!insert_item(&chart, start_production, alternative, 0U, 0U, 0U)) {
            goto cleanup;
        }
    }
    for (position = 0U; position <= token_count; ++position) {
        if (!close_parallel_position(&pool,
                                     &generation,
                                     position,
                                     stats)) {
            goto cleanup;
        }
        if (position < token_count) {
            if (!scan_parallel_position(&pool,
                                        &generation,
                                        position,
                                        stats)) {
                goto cleanup;
            }
            if (pbnfc_chart_set_size(pbnfc_chart_set_const(&chart,
                                                           position + 1U)) ==
                0U) {
                rejection_position = position;
                rejection_set = pbnfc_chart_set_const(&chart, position);
                break;
            }
        }
    }
    if (has_accepting_item(&chart,
                           grammar,
                           start_production,
                           token_count)) {
        result = PBNFC_RECOGNITION_ACCEPTED;
        goto cleanup;
    }
    if (rejection_set == NULL) {
        rejection_position = token_count;
        rejection_set = pbnfc_chart_set_const(&chart, token_count);
    }
    expected = expected_detail(rejection_set, grammar);
    if (expected == NULL) {
        goto cleanup;
    }
    rejection_location = rejection_position < token_count
                             ? tokens[rejection_position].location
                             : eof_location(tokens, token_count);
    if (diagnostics != NULL) {
        (void)pbnfc_rejection_emit(diagnostics,
                                   expected,
                                   &rejection_location);
    }
    result = PBNFC_RECOGNITION_REJECTED;

cleanup:
    free(expected);
    candidate_vectors_free(generation.candidates);
    pbnfc_worker_pool_free(&pool);
    pbnfc_chart_free(&chart);
    return result;
}
